<x-layout title="Projects"><div class="heading"><div><span class="eyebrow">PROJECT WORKSPACE</span><h1>Projects<span class="heading-dot">.</span></h1><p class="muted">Browse, plan, and manage your client projects.</p></div>@if(auth()->user()->role==='admin')<button class="button" data-open="new-project">+ New project</button>@endif</div><div class="section-head"><h2>All projects <span class="count">{{ $projects->count() }}</span></h2><form class="filters" method="get" action="{{ route('projects.index') }}"><input aria-label="Search projects" name="q" placeholder="⌕ Search projects…" value="{{ request('q') }}"><select aria-label="Project status" name="status" onchange="this.form.requestSubmit()"><option value="">All statuses</option>@foreach(['active'=>'Active','on_hold'=>'On hold','completed'=>'Completed','archived'=>'Archived'] as $key=>$label)<option value="{{ $key }}" @selected(request('status')===$key)>{{ $label }}</option>@endforeach</select><select aria-label="Client" name="client"><option value="">All clients</option>@foreach($clients as $c)<option value="{{ $c->id }}" @selected(request("client")==$c->id)>{{ $c->name }}</option>@endforeach</select><select aria-label="Assignee" name="assignee"><option value="">All assignees</option>@foreach($users as $u)<option value="{{ $u->id }}" @selected(request("assignee")==$u->id)>{{ $u->name }}</option>@endforeach</select><button class="button secondary">Search</button></form></div><div class="project-grid">@forelse($projects as $p)<a class="project-card" href="/projects/{{ $p->id }}"><div class="row between"><span class="project-icon">{{ strtoupper(substr($p->name,0,2)) }}</span><span class="badge {{ $p->status }}">{{ str_replace('_',' ',ucfirst($p->status)) }}</span></div><div><span class="eyebrow">{{ $p->client->name }}</span><h2>{{ $p->name }}</h2><p class="muted clamp">{{ $p->description ?: 'Your next great project starts here.' }}</p></div><div><div class="row between small"><span>Project progress</span><strong>{{